// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.30;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// Mock AMM de producto constante (x*y=k) con un solo par INCOME_TOKEN/TOKEN.
contract LinealDex is ReentrancyGuard {
    using SafeERC20 for IERC20;

    address public immutable TOKEN;
    address public immutable INCOME_TOKEN;

    uint256 public reserveToken;
    uint256 public reserveIncome;

    // TWAP (acumulador de precio estilo Uniswap V2)
    uint256 public priceCumulativeLast; // INCOME por TOKEN (1e18) * segundos
    uint256 public blockTimestampLast;

    uint256 public constant FEE_BPS = 30; // 0.3%, queda en el pool y sube k

    // Participación de liquidez (simplificada, sin ERC20 de LP)
    uint256 public totalShares;
    mapping(address => uint256) public sharesOf;

    event Swap(address indexed to, address tokenIn, uint256 amountIn, uint256 amountOut);
    event LiquidityAdded(address indexed to, uint256 amountIncome, uint256 amountToken, uint256 shares);
    event LiquidityRemoved(address indexed from, uint256 amountIncome, uint256 amountToken, uint256 shares);

    constructor(address _token, address _income) {
        TOKEN = _token;
        INCOME_TOKEN = _income;
    }

    // ───────────── Vistas ─────────────

    /// Cantidad de salida según reservas y fee (la fórmula de Uniswap V2).
    function getAmountOut(uint256 amountIn, uint256 reserveIn, uint256 reserveOut)
    public pure returns (uint256)
    {
        require(amountIn > 0, "Mock: zero input");
        require(reserveIn > 0 && reserveOut > 0, "Mock: no liquidity");
        uint256 inWithFee = amountIn * (10_000 - FEE_BPS);
        return (inWithFee * reserveOut) / (reserveIn * 10_000 + inWithFee);
    }

    /// Precio spot: unidades de TOKEN por 1 unidad de INCOME_TOKEN (escala 1e18).
    function spotPrice() external view returns (uint256) {
        require(reserveIncome > 0, "Mock: no liquidity");
        return (reserveToken * 1e18) / reserveIncome;
    }

    function getAmountsOut(uint256 amountIn, address[] calldata path)
    external view returns (uint256[] memory amounts)
    {
        require(path.length == 2, "Mock: invalid path");
        (uint256 rIn, uint256 rOut) = _reservesFor(path[0], path[1]);
        amounts = new uint256[](2);
        amounts[0] = amountIn;
        amounts[1] = getAmountOut(amountIn, rIn, rOut);
    }

    // ───────────── Swap ─────────────

    function swapExactTokensForTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external nonReentrant returns (uint256[] memory amounts) {
        require(block.timestamp <= deadline, "Mock: expired");
        require(path.length == 2, "Mock: invalid path");

        (uint256 rIn, uint256 rOut) = _reservesFor(path[0], path[1]);
        uint256 amountOut = getAmountOut(amountIn, rIn, rOut);
        require(amountOut >= amountOutMin, "Mock: Swap failed (slippage)");
        _update();   // <-- aquí también
        IERC20(path[0]).safeTransferFrom(msg.sender, address(this), amountIn);
        IERC20(path[1]).safeTransfer(to, amountOut);

        // Actualiza reservas: el precio se mueve aquí
        if (path[0] == INCOME_TOKEN) {
            reserveIncome += amountIn;
            reserveToken -= amountOut;
        } else {
            reserveToken += amountIn;
            reserveIncome -= amountOut;
        }

        amounts = new uint256[](2);
        amounts[0] = amountIn;
        amounts[1] = amountOut;
        emit Swap(to, path[0], amountIn, amountOut);
    }

    // ───────────── Liquidez ─────────────

    function addLiquidity(
        address tokenA,
        address tokenB,
        uint256 amountADesired,
        uint256 amountBDesired,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline
    ) external nonReentrant returns (uint256 amountA, uint256 amountB, uint256 liquidity) {
        require(block.timestamp <= deadline, "Mock: expired");
        require(
            (tokenA == INCOME_TOKEN && tokenB == TOKEN) || (tokenA == TOKEN && tokenB == INCOME_TOKEN),
            "Mock: invalid pair"
        );
        _update();   // <-- aquí también
        // Normaliza a (income, token)
        bool aIsIncome = tokenA == INCOME_TOKEN;
        uint256 dIncome = aIsIncome ? amountADesired : amountBDesired;
        uint256 dToken  = aIsIncome ? amountBDesired : amountADesired;
        uint256 minIncome = aIsIncome ? amountAMin : amountBMin;
        uint256 minToken  = aIsIncome ? amountBMin : amountAMin;

        uint256 aIncome;
        uint256 aToken;
        if (reserveIncome == 0 && reserveToken == 0) {
            // Primer depósito: fija el precio inicial
            (aIncome, aToken) = (dIncome, dToken);
        } else {
            // Respeta la proporción actual para no mover el precio
            uint256 optToken = (dIncome * reserveToken) / reserveIncome;
            if (optToken <= dToken) {
                require(optToken >= minToken, "Mock: insufficient token amount");
                (aIncome, aToken) = (dIncome, optToken);
            } else {
                uint256 optIncome = (dToken * reserveIncome) / reserveToken;
                require(optIncome <= dIncome && optIncome >= minIncome, "Mock: insufficient income amount");
                (aIncome, aToken) = (optIncome, dToken);
            }
        }

        IERC20(INCOME_TOKEN).safeTransferFrom(msg.sender, address(this), aIncome);
        IERC20(TOKEN).safeTransferFrom(msg.sender, address(this), aToken);

        if (totalShares == 0) {
            liquidity = _sqrt(aIncome * aToken);
        } else {
            uint256 s1 = (aIncome * totalShares) / reserveIncome;
            uint256 s2 = (aToken * totalShares) / reserveToken;
            liquidity = s1 < s2 ? s1 : s2;
        }
        require(liquidity > 0, "Mock: zero liquidity");

        reserveIncome += aIncome;
        reserveToken += aToken;
        totalShares += liquidity;
        sharesOf[to] += liquidity;

        (amountA, amountB) = aIsIncome ? (aIncome, aToken) : (aToken, aIncome);
        emit LiquidityAdded(to, aIncome, aToken, liquidity);
    }

    /// Extra para tests: retirar liquidez.
    function _reservesFor(address tokenIn, address tokenOut)
    internal view returns (uint256 rIn, uint256 rOut)
    {
        if (tokenIn == INCOME_TOKEN && tokenOut == TOKEN) return (reserveIncome, reserveToken);
        if (tokenIn == TOKEN && tokenOut == INCOME_TOKEN) return (reserveToken, reserveIncome);
        revert("Mock: Invalid path");
    }

    function _sqrt(uint256 y) internal pure returns (uint256 z) {
        if (y > 3) {
            z = y;
            uint256 x = y / 2 + 1;
            while (x < z) { z = x; x = (y / x + x) / 2; }
        } else if (y != 0) {
            z = 1;
        }
    }

    /// Liquidez total del pool: reservas de cada token y participaciones emitidas.
    /// Valor total del pool expresado en INCOME_TOKEN.
    /// Al precio spot, ambos lados valen lo mismo, así que el total es 2 * reserveIncome.
    function getTotalLiquidity()
    external
    view
    returns (
        uint256 ingreso,
        uint256 token,
        uint256 participaciones
    )
    {
        return (reserveIncome, reserveToken, totalShares);
    }

    function getTotalLiquidityInIncome()
    external
    view
    returns (uint256)
    {
        return reserveIncome * 2;
    }
    function _update() private {
        uint256 dt = block.timestamp - blockTimestampLast;
        if (dt > 0 && reserveToken > 0 && reserveIncome > 0) {
            priceCumulativeLast += (reserveIncome * 1e18 / reserveToken) * dt;
        }
        blockTimestampLast = block.timestamp;
    }

    /// Acumulador al instante actual, sin necesidad de que alguien opere.
    function currentPriceCumulative() public view returns (uint256 cumulative, uint256 timestamp) {
        cumulative = priceCumulativeLast;
        uint256 dt = block.timestamp - blockTimestampLast;
        if (dt > 0 && reserveToken > 0 && reserveIncome > 0) {
            cumulative += (reserveIncome * 1e18 / reserveToken) * dt;
        }
        timestamp = block.timestamp;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.30;

import "../../governance/LinealQorum.sol";
import "../../institution/LinealInstitution.sol";
import "../paymasters/LinealRouter.sol";
import "../token/LinealToken.sol";
import "./LinealDex.sol";
import "./LinealMilestones.sol";
import "./LinealSeed.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import {LinealBank} from "../banks/LinealBank.sol";

/**
 * @title Lineal Liquidity by Lineal Qorum Protocol
 * @notice
 */
contract LinealLiquidity is LinealQorum, Pausable {

    LinealToken public immutable qorumToken;
    LinealBank public immutable institutionalBank;
    LinealInstitution public immutable institutionAddress;
    uint256 public initialPriceToken;
    uint256 public initialPriceNft;
    bool public isSeedLaunched = false;
    bool public isPreSeedLaunched = false;

    event UnlockExecuted(uint256 amount, uint256 alpha, uint256 idp);
    event BuybackAndBurn(uint256 incomeSpent, uint256 qorumsBurned);

    constructor(
        address _institutionAddress,
        address _bankAddress,
        address[] memory _machines,
        address[] memory _institutions,
        address[] memory _humans,
        uint256 _requiredMachines,
        uint256 _requiredInstitutions,
        uint256 _requiredHumans,
        uint256 _recoveryQuorum
    ) LinealQorum(
    _machines,
    _requiredMachines,
    _institutions,
    _requiredInstitutions,
    _humans,
    _requiredHumans,
    _recoveryQuorum) {
        institutionalBank = LinealBank(_bankAddress);
        institutionAddress = LinealInstitution(_institutionAddress);
    }

    // --- FUNCIONES DE SEGURIDAD Y ADMINISTRACIÓN ---

    function pause() public onlyQorum {
        bytes32 txHash = _computeActionHash("pause", abi.encode(""));
        if (!confirmServers(txHash, "pause")) return;
        _pause();
    }

    function unpause() public onlyQorum {
        bytes32 txHash = _computeActionHash("pause", abi.encode(""));
        if (!confirmServers(txHash, "pause")) return;
        _unpause();
    }

    function launchSeed(
        address _linealSeed
    ) external onlyServers {
        require(isSeedLaunched == false, "Launched");
        bytes32 txHash = _computeActionHash("launchSeed",
            abi.encode(
                _linealSeed
            ));
        if (!confirmServers(txHash, "launchSeed")) return;
        address linealToken = institutionAddress.linealCoin();
        uint256 totalTokenSale = LinealSeed(_linealSeed).totalTokenSale();
        LinealToken(linealToken).approve(_linealSeed, totalTokenSale);
        LinealToken(linealToken).transfer(_linealSeed, totalTokenSale);
        isSeedLaunched = true;
    }

    function launchPreSeed(uint256 totalAmount, uint256 _initialPriceToken, uint256 _initialPriceNft
    ) external onlyServers {
        require(isPreSeedLaunched == false, "Launched");
        bytes32 txHash = _computeActionHash("launchPreSeed",
            abi.encode(totalAmount));
        if (!confirmServers(txHash, "launchPreSeed")) return;
        bytes32 institutionalId = institutionAddress.institutionAccountId();
        address linealToken = institutionAddress.linealCoin();
        initialPriceToken = _initialPriceToken;
        initialPriceNft = _initialPriceNft;
        LinealToken(linealToken).approve(address(institutionalBank), totalAmount * 1e18);
        institutionalBank.deposit(institutionalId, linealToken, totalAmount * 1e18);
        isPreSeedLaunched = true;
    }

    function withdrawUnsoldTokens(address _linealSeed) external onlyServers {
        bytes32 txHash = _computeActionHash("withdrawUnsoldTokens", abi.encode(_linealSeed));
        if (!confirmServers(txHash, "withdrawUnsoldTokens")) return;
        LinealToken saleToken = LinealSeed(_linealSeed).saleToken();
        LinealSeed(_linealSeed).withdrawUnsoldTokens();
        uint256 balance = saleToken.balanceOf(address (this));
        bytes32 id = institutionAddress.institutionAccountId();
        institutionalBank.deposit(id, address(saleToken), balance);
    }
    // --- LÓGICA CENTRAL LCL/IDP (CALCULADORA) ---

    /**
     * @notice Implementa la lógica LCL/IDP del documento técnico.
     * @param _alpha Índice Alpha.
     * @param _idp Índice IDP.
     */
    function _calculateUnlock(uint256 _alpha, uint256 _idp)
    internal
    pure
    returns (uint256)
    {
        // 1. Componente IDP (Porcentaje Base de Desbloqueo)
        uint256 idpBasePercent;

        // IDP >= 100 -> 75% | IDP > 66 -> 30% | else -> 0%
        if (_idp >= 100) {
            idpBasePercent = 75;
        } else if (_idp > 66) {
            idpBasePercent = 30;
        } else {
            idpBasePercent = 0;
        }

        // 2. Componente LCL (Factor de Ajuste: 0.8x o 1.0x)
        uint256 lclAdjustment;

        // Alpha < 100 (0.8x) | Alpha >= 100 (1.0x)
        if (_alpha < 93) {
            lclAdjustment = 50; // 0.8x
        } else if (_alpha >= 12) {
            lclAdjustment = 110; // 1.0x
        }

        // Cálculo Final: FinalUnlock = MaxUnlock * (IDP %) * (LCL Adjust)

        // Aplica el factor IDP (dividiendo por 100)
        uint256 rawUnlock = (idpBasePercent) / 100;

        // Aplica el factor LCL (dividiendo por 100)
        uint256 finalUnlock = (rawUnlock * lclAdjustment) / 100;

        return finalUnlock;
    }

    /**
     * @notice Ejecuta el cálculo, desbloquea y acuña tokens al destinatario.
     * @dev Requiere validación del LinealQorum Multisig
     */
    function unlockAndMint(address payable _recipient, uint256 _token, address _tokenAddress, address _milestoneAddress,
        address _linealSwap)
    public
    onlyServers
    whenNotPaused
    {
        bytes32 txHash = _computeActionHash("unlockAndMint", abi.encode(_recipient, _token));
        if (!confirmServers(txHash, "unlockAndMint")) return;

        uint256 _alpha = _calculateAlpha(_linealSwap, _tokenAddress);
        uint256 _idp = LinealMilestones(_milestoneAddress).idp();

        // 2. Aplicar validación de emisión (Condición LCL)
        require(_alpha >= 93, "LCL: Liquidez insuficiente (alpha < 0.93).");
        // 3. Aplicar validación de desbloqueo (Condición IDP)
        require(_idp >= 66, "IDP: Desempeno bajo (IDP < 0.66).");

        // 4. Calcular el monto final de desbloqueo
        uint256 unlockAmount = _calculateUnlock(_alpha, _idp);

        // Asegurar que no se exceda el suministro restante

        // 5. Liberar tokens desde la reserva
        if (unlockAmount > 0) {
            LinealToken(_tokenAddress).mint(_recipient, unlockAmount);
            LinealRouter(_recipient).distributeRevenue(unlockAmount);
        }

        emit UnlockExecuted(unlockAmount, _alpha, _idp);
    }


    /**
     * @dev Compra tokens QORUMS y los quema (Buyback & Burn).
     */
    function _executeBuybackAndBurn(uint256 incomeAmount, address _tokenAddress, address dexRouter, address
        _incomeToken)
    internal {
        address[] memory path = new address[](2);
        path[0] = address(_incomeToken);
        path[1] = address(_tokenAddress);

        uint256[] memory amounts = LinealDex(dexRouter).swapExactTokensForTokens(
            incomeAmount,
            1, // amountOutMin (tolerancia de deslizamiento baja para MVP — revisar antes de producción)
            path,
            address(this),
            block.timestamp
        );

        uint256 qorumsToReturn = amounts[amounts.length - 1];

        if (qorumsToReturn > 0) {
            LinealToken(_tokenAddress).burn(address(this), qorumsToReturn);
            emit BuybackAndBurn(incomeAmount, qorumsToReturn);
        }
    }


    function _calculateAlpha(
        address _linealSwap,
        address _linealToken
    ) internal view returns (uint256 _alpha) {
        (
            uint256 reserveIncome,
            uint256 reserveToken,
            uint256 totalShares
        ) = LinealDex(_linealSwap).getTotalLiquidity();

        (
            uint256 cumulative,
            uint256 timestamp
        ) = LinealDex(_linealSwap).currentPriceCumulative();

        uint256 circulatingSupply =
                                LinealToken(_linealToken).getCirculatingSupply();

        // Evitar divisiones por cero.
        if (
            circulatingSupply == 0 ||
            cumulative == 0 ||
            reserveIncome == 0 ||
            reserveToken == 0
        ) {
            return 0;
        }

        // No calcular alpha con un acumulador TWAP sin un periodo
        // de observación definido.
        timestamp;

        uint256 spotPrice =
            (reserveIncome * 1e18) / reserveToken;

        _alpha = (reserveIncome * 1e18) / circulatingSupply;

        // Variables recuperadas para mantener explícita la interfaz.
        totalShares;
        cumulative;
        spotPrice;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.30;

import "../../governance/LinealQorum.sol";

/// Interfaz mínima de LinealCitizens (NFT soulbound, un perfil por wallet).
interface ILinealCitizens {
    function walletToToken(address wallet) external view returns (uint256); // 0 si no tiene perfil
    function tokenCounter() external view returns (uint256);               // tokenIds secuenciales, nunca se reutilizan
}

/**
 * @title LinealMilestones - NeoQuor
 * @notice Hitos del proyecto validados por votación de los ciudadanos.
 *         El IDP (índice de desempeño) es la suma de los pesos de los hitos aprobados (0-100).
 *         Un ciudadano = un voto. El padrón se congela al abrir cada hito.
 */
contract LinealMilestones is LinealQorum {

    enum Status { None, Voting, Approved, Rejected, Cancelled }

    struct Milestone {
        uint8 weight;           // puntos que aporta al IDP
        uint64 start;
        uint64 end;
        uint32 votesFor;
        uint32 votesAgainst;
        uint32 citizensAtStart; // padrón congelado (tokenCounter al abrir)
        Status status;
    }

    ILinealCitizens public immutable citizens;

    uint256 public constant MIN_PARTICIPATION_BPS = 2_000; // 20% del padrón
    uint256 public constant MIN_APPROVAL_BPS = 6_600;      // 66% de los votos emitidos
    uint64 public constant MIN_DURATION = 3 days;
    uint64 public constant MAX_DURATION = 30 days;

    /// Peso comprometido: hitos en votación + aprobados. Nunca supera 100.
    uint256 public totalWeight;
    /// Peso de los hitos aprobados = IDP actual.
    uint256 public approvedWeight;

    Milestone[] public milestones;
    mapping(uint256 => mapping(address => bool)) public hasVoted;

    event MilestoneCreated(uint256 indexed id, uint8 weight, uint64 start, uint64 end, uint32 citizensAtStart);
    event Voted(uint256 indexed id, address indexed voter, bool support);
    event MilestoneFinalized(uint256 indexed id, Status status, uint32 votesFor, uint32 votesAgainst);
    event MilestoneCancelled(uint256 indexed id);

    constructor(
        address _citizens,
        address[] memory _machines,
        address[] memory _institutions,
        address[] memory _humans,
        uint256 _requiredMachines,
        uint256 _requiredInstitutions,
        uint256 _requiredHumans,
        uint256 _recoveryQuorum
    ) LinealQorum(
    _machines,
    _requiredMachines,
    _institutions,
    _requiredInstitutions,
    _humans,
    _requiredHumans,
    _recoveryQuorum
    ) {
        require(_citizens != address(0), "Invalid citizens");
        citizens = ILinealCitizens(_citizens);
    }

    // ───────────── Gobernanza (quórum) ─────────────

    /// @notice Abre la votación de un nuevo hito. Requiere confirmación del quórum.
    function createMilestone(uint8 weight, uint64 duration) external onlyServers {
        require(weight > 0, "Weight = 0");
        require(duration >= MIN_DURATION && duration <= MAX_DURATION, "Bad duration");
        require(totalWeight + weight <= 100, "Weights > 100");

        // El id del hito va en el hash: cada hito necesita su propia confirmación
        bytes32 txHash = _computeActionHash(
            "createMilestone",
            abi.encode(weight, duration, milestones.length)
        );
        if (!confirmServers(txHash, "createMilestone")) return;

        uint256 snapshot = citizens.tokenCounter();
        require(snapshot > 0, "No citizens");

        totalWeight += weight;

        uint256 id = milestones.length;
        uint64 start = uint64(block.timestamp);
        uint64 end = start + duration;

        milestones.push(Milestone({
            weight: weight,
            start: start,
            end: end,
            votesFor: 0,
            votesAgainst: 0,
            citizensAtStart: uint32(snapshot),
            status: Status.Voting
        }));

        emit MilestoneCreated(id, weight, start, end, uint32(snapshot));
    }

    /// @notice Freno de emergencia: el quórum puede cancelar una votación abierta.
    function cancelMilestone(uint256 id) external onlyQorum {
        Milestone storage m = milestones[id];
        require(m.status == Status.Voting, "Not voting");

        bytes32 txHash = _computeActionHash("cancelMilestone", abi.encode(id));
        if (!confirmServers(txHash, "cancelMilestone")) return;

        m.status = Status.Cancelled;
        totalWeight -= m.weight; // libera el peso para volver a proponerlo

        emit MilestoneCancelled(id);
    }

    // ───────────── Votación (ciudadanos) ─────────────

    /// @notice Vota un hito. Elegible: perfil de LinealCitizens emitido antes de abrir el hito.
    function vote(uint256 id, bool support) external {
        Milestone storage m = milestones[id];
        require(m.status == Status.Voting && block.timestamp <= m.end, "Not open");

        uint256 tokenId = citizens.walletToToken(msg.sender);
        require(tokenId != 0 && tokenId <= m.citizensAtStart, "Not eligible");
        require(!hasVoted[id][msg.sender], "Already voted");

        hasVoted[id][msg.sender] = true;

        if (support) {
            m.votesFor++;
        } else {
            m.votesAgainst++;
        }

        emit Voted(id, msg.sender, support);
    }

    /// @notice Cierra la votación al vencer el plazo. Cualquiera puede llamarla.
    function finalize(uint256 id) external {
        Milestone storage m = milestones[id];
        require(m.status == Status.Voting && block.timestamp > m.end, "Not ready");

        uint256 votes = uint256(m.votesFor) + m.votesAgainst;
        bool participated = votes * 10_000 >= uint256(m.citizensAtStart) * MIN_PARTICIPATION_BPS;
        bool approved = votes > 0 && uint256(m.votesFor) * 10_000 >= votes * MIN_APPROVAL_BPS;

        if (participated && approved) {
            m.status = Status.Approved;
            approvedWeight += m.weight;
        } else {
            m.status = Status.Rejected;
            totalWeight -= m.weight; // libera el peso: el hito puede volver a proponerse
        }

        emit MilestoneFinalized(id, m.status, m.votesFor, m.votesAgainst);
    }

    // ───────────── Vistas ─────────────

    /// @notice Índice de desempeño: suma de pesos de hitos aprobados (0-100). O(1).
    function idp() external view returns (uint256) {
        return approvedWeight;
    }

    function milestonesCount() external view returns (uint256) {
        return milestones.length;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {LinealToken} from "../token/LinealToken.sol";

/**
 * @title VestedICOERC20
 * @notice ICO cuyo pago se realiza en un token ERC20 (ej. USDC/USDT) en vez de ETH.
 *         Liberación de los tokens vendidos:
 *         - 20% reclamable apenas se finaliza la venta (TGE)
 *         - 80% reclamable tras un cliff de 6 meses desde el TGE
 *           (70% pedido + 10% restante asumido; ajustar CLIFF_BPS si corresponde)
 * @dev El owner debe transferir al contrato los tokens a vender
 *      (hardCap * rate) antes de iniciar la venta.
 *      Los compradores deben hacer `approve` del paymentToken antes de `buy()`.
 */
contract LinealSeed is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ---------------------------------------------------------------------
    // Parámetros de vesting (en basis points, 10_000 = 100%)
    // ---------------------------------------------------------------------
    uint256 public constant BPS = 10_000;
    uint256 public constant IMMEDIATE_BPS = 2_000; // 20%
    uint256 public constant CLIFF_BPS = 8_000; // 80% (70% + 10% restante)
    uint256 public constant CLIFF_DURATION = 180 days; // ~6 meses

    // ---------------------------------------------------------------------
    // Configuración de la venta
    // ---------------------------------------------------------------------
    LinealToken public saleToken;
    IERC20 public immutable paymentToken; // token con el que se paga (USDC, USDT, etc.)
    uint256 public totalTokenSale;

    /// @dev unidades mínimas de saleToken por 1 unidad mínima de paymentToken.
    ///      Ej: paymentToken USDC (6 dec), saleToken 18 dec, precio 0.05 USDC por token
    ///      => 1 USDC compra 20 tokens => rate = 20 * 1e18 / 1e6 = 20e12.
    uint256 public immutable rate;

    uint256 public immutable softCap; // en unidades mínimas de paymentToken
    uint256 public immutable hardCap; // en unidades mínimas de paymentToken
    uint256 public immutable startTime;
    uint256 public immutable endTime;
    uint256 public immutable minContribution; // en unidades mínimas de paymentToken

    // ---------------------------------------------------------------------
    // Estado
    // ---------------------------------------------------------------------
    uint256 public totalRaised;
    address public linealLiquidity;
    uint256 public totalSold; // saleTokens vendidos (unidades mínimas)
    uint256 public totalClaimed; // saleTokens ya reclamados por compradores
    bool public finalized;
    bool public successful;
    uint256 public tgeTime;

    mapping(address => uint256) public contributed; // paymentToken aportado
    mapping(address => uint256) public purchased; // saleTokens comprados
    mapping(address => uint256) public claimed; // saleTokens ya reclamados

    // ---------------------------------------------------------------------
    // Eventos
    // ---------------------------------------------------------------------
    event Purchased(address indexed buyer, uint256 paymentAmount, uint256 tokenAmount);
    event Finalized(bool successful, uint256 totalRaised, uint256 tgeTime);
    event Claimed(address indexed buyer, uint256 amount);
    event SaleTokenSet(address indexed saleToken);
    event Refunded(address indexed buyer, uint256 paymentAmount);
    event FundsWithdrawn(address indexed to, uint256 amount);
    event UnsoldTokensWithdrawn(address indexed to, uint256 amount);

    // ---------------------------------------------------------------------
    // Errores
    // ---------------------------------------------------------------------
    error SaleNotActive();
    error SaleTokenNotSet();
    error SaleNotEnded();
    error AlreadyFinalized();
    error NotFinalized();
    error BelowMinContribution();
    error HardCapExceeded();
    error NothingToClaim();
    error NotRefundable();
    error NotSuccessful();
    error InvalidParams();
    error FeeOnTransferNotSupported();

    constructor(
        address _paymentToken,
        address _linealLiquidity,
        uint256 _totalTokenSale,
        address _saleToken,
        uint256 _rate,
        uint256 _softCap,
        uint256 _hardCap,
        uint256 _startTime,
        uint256 _endTime,
        uint256 _minContribution
    ) Ownable(_linealLiquidity) {
        if (
            _paymentToken == address(0) ||
            _rate == 0 ||
            _totalTokenSale == 0 ||
            _hardCap == 0 ||
            _softCap > _hardCap ||
            _startTime < block.timestamp ||
            _endTime <= _startTime ||
            IMMEDIATE_BPS + CLIFF_BPS != BPS
        ) revert InvalidParams();

        paymentToken = IERC20(_paymentToken);
        saleToken = LinealToken(_saleToken);
        linealLiquidity = _linealLiquidity;
        rate = _rate;
        softCap = _softCap;
        hardCap = _hardCap;
        startTime = _startTime;
        endTime = _endTime;
        minContribution = _minContribution;
        totalTokenSale = _totalTokenSale;
    }

    // ---------------------------------------------------------------------
    // Compra
    // ---------------------------------------------------------------------
    /// @param paymentAmount Monto en unidades mínimas del paymentToken.
    ///        Requiere `approve` previo a este contrato.
    function buy(uint256 paymentAmount) external nonReentrant {
        require(address(saleToken) != address(0), "CLP: Reserve bank not set");
        if (finalized || block.timestamp < startTime || block.timestamp > endTime) {
            revert SaleNotActive();
        }
        if (paymentAmount < minContribution || paymentAmount == 0) {
            revert BelowMinContribution();
        }
        if (totalRaised + paymentAmount > hardCap) revert HardCapExceeded();

        // Se verifica lo realmente recibido para rechazar tokens con comisión por transferencia
        uint256 balanceBefore = paymentToken.balanceOf(address(this));
        paymentToken.safeTransferFrom(msg.sender, address(this), paymentAmount);
        uint256 received = paymentToken.balanceOf(address(this)) - balanceBefore;
        if (received != paymentAmount) revert FeeOnTransferNotSupported();

        uint256 tokenAmount = paymentAmount * rate;

        totalRaised += paymentAmount;
        totalSold += tokenAmount;
        contributed[msg.sender] += paymentAmount;
        purchased[msg.sender] += tokenAmount;

        emit Purchased(msg.sender, paymentAmount, tokenAmount);
    }

    // ---------------------------------------------------------------------
    // Finalización
    // ---------------------------------------------------------------------
    /// @notice Cualquiera puede finalizar al terminar el plazo o al llegar al hardCap.
    function finalize() external {
        if (finalized) revert AlreadyFinalized();
        if (block.timestamp <= endTime && totalRaised < hardCap) revert SaleNotEnded();

        finalized = true;

        if (totalRaised >= softCap) {
            successful = true;
            tgeTime = block.timestamp;
        }

        emit Finalized(successful, totalRaised, tgeTime);
    }

    // ---------------------------------------------------------------------
    // Reclamo de tokens (vesting)
    // ---------------------------------------------------------------------
    /// @notice saleTokens que el comprador puede reclamar ahora mismo.
    function claimable(address buyer) public view returns (uint256) {
        if (!finalized || !successful) return 0;

        uint256 total = purchased[buyer];
        uint256 unlocked = (total * IMMEDIATE_BPS) / BPS;

        if (block.timestamp >= tgeTime + CLIFF_DURATION) {
            unlocked = total; // 20% + 80%
        }

        return unlocked - claimed[buyer];
    }

    function claim() external nonReentrant {
        uint256 amount = claimable(msg.sender);
        if (amount == 0) revert NothingToClaim();

        claimed[msg.sender] += amount;
        totalClaimed += amount;
        LinealToken(address(saleToken)).transfer(msg.sender, amount);


        emit Claimed(msg.sender, amount);
    }

    // ---------------------------------------------------------------------
    // Reembolso si no se alcanzó el softCap
    // ---------------------------------------------------------------------
    function refund() external nonReentrant {
        if (!finalized || successful) revert NotRefundable();

        uint256 amount = contributed[msg.sender];
        if (amount == 0) revert NothingToClaim();

        contributed[msg.sender] = 0;
        purchased[msg.sender] = 0;

        LinealToken(address(saleToken)).transfer(msg.sender, amount);

        emit Refunded(msg.sender, amount);
    }

    // ---------------------------------------------------------------------
    // Administración
    // ---------------------------------------------------------------------
    /// @notice Retira el paymentToken recaudado (solo si la venta fue exitosa).
    function withdrawFunds() external onlyOwner {
        if (!finalized) revert NotFinalized();
        if (!successful) revert NotSuccessful();

        uint256 balance = paymentToken.balanceOf(address(this));
        paymentToken.transfer(linealLiquidity, balance);
        emit FundsWithdrawn(linealLiquidity, balance);
    }

    /// @notice Retira saleTokens no vendidos (venta exitosa) o todos (venta fallida).
    ///         Nunca toca los tokens pendientes de reclamo de los compradores.
    function withdrawUnsoldTokens() external onlyOwner {
        if (!finalized) revert NotFinalized();

        uint256 balance = LinealToken(address(saleToken)).balanceOf(address(this));
        uint256 reserved = successful ? (totalSold - totalClaimed) : 0;
        uint256 free = balance > reserved ? balance - reserved : 0;

        LinealToken(address(saleToken)).transfer(linealLiquidity, free);
        emit UnsoldTokensWithdrawn(linealLiquidity, free);
    }
}

project/contracts/economy/paymasters/Lin.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.30;

import "@openzeppelin/contracts/utils/Pausable.sol";
import "../../governance/LinealQorum.sol";
import "../../economy/interfaces/IQorumsToken.sol";
import "../../economy/interfaces/IIncomeToken.sol";

/**
 * @title PaymentRouter
 * @notice Splitter de ingresos genérico y estándar (no ligado a roles fijos).
 * El multisig define post-despliegue N destinatarios, cada uno con:
 *   - un porcentaje (basis points, base 10000)
 *   - un tipo de acción: TRANSFER (transferencia directa) o BUYBACK_BURN (swap + burn)
 * Este contrato debe tener el BURNER_ROLE en QorumsToken.
 */
contract LinealRouter is LinealQorum, Pausable {

    IQorumsToken public immutable QORUMS;
    IIncomeToken public immutable INCOME_TOKEN; // Ej. USDC

    address public linealLiquidity; // Contrato autorizado para enviar fondos

    uint256 public constant BPS_DENOMINATOR = 10000;
    uint256 public constant MAX_RECIPIENTS = 20; // límite de seguridad para evitar gas-DoS en el loop

    struct Recipient {
        address account; // ignorado cuando distType == BUYBACK_BURN
        uint256 bps;
        string label;    // etiqueta legible, informativa (ej. "Founder", "Rewards Pool", "Protocol Burn")
    }

    // Tokenomics vigente, 100% configurable por el multisig vía setDistribution()
    Recipient[] public recipients;

    event RevenueDistributed(uint256 incomeAmount, uint256 recipientsCount);
    event RecipientPaid(uint256 indexed index, address indexed account, uint256 amount);
    event DistributionUpdated(uint256 recipientsCount);

    constructor(
        address[] memory _machines,
        address[] memory _institutions,
        address[] memory _humans,
        uint256 _requiredMachines,
        uint256 _requiredInstitutions,
        uint256 _requiredHumans,
        uint256 _recoveryQuorum,
        address _qorumsTokenAddress,
        address _incomeTokenAddress
    ) LinealQorum(_machines, _requiredMachines, _institutions, _requiredInstitutions, _humans, _requiredHumans, _recoveryQuorum) {
        QORUMS = IQorumsToken(_qorumsTokenAddress);
        INCOME_TOKEN = IIncomeToken(_incomeTokenAddress);
    }

    // --- SEGURIDAD Y ADMINISTRACIÓN MULTISIG ---

    function setFeeSplitter(address _linealLiquidity) public onlyServers {
        bytes32 txHash = keccak256(abi.encodePacked("setFeeSplitter", _linealLiquidity,
            actionNonce["setFeeSplitter"]));
        if (confirmServers(txHash, "setFeeSplitter")) {
            linealLiquidity = _linealLiquidity;
        }
    }

    /**
     * @notice Redefine por completo el tokenomics de distribución. Estándar y genérico:
     * el multisig puede definir cualquier número de destinatarios (hasta MAX_RECIPIENTS),
     * cada uno con su propio porcentaje y tipo de acción.
     * @dev Los `bps` deben sumar exactamente 10000. Para entradas TRANSFER, `accounts[i]`
     * es la dirección destino. Para BUYBACK_BURN, `accounts[i]` se ignora (pasar address(0)).
     * Requiere confirmServeración multisig, igual que el resto de funciones administrativas.
     */
    function setDistribution(
        address[] calldata accounts,
        uint256[] calldata bpsValues,
        string[] calldata labels
    ) public onlyServers {
        uint256 len = accounts.length;
        require(len > 0 && len <= MAX_RECIPIENTS, "PayMaster: invalid recipients length");
        require(
            bpsValues.length == len && labels.length == len,
            "PayMaster: array length mismatch"
        );

        uint256 totalBps;
        for (uint256 i = 0; i < len; i++) {
            totalBps += bpsValues[i];
        }
        require(totalBps == BPS_DENOMINATOR, "PayMaster: bps must sum to 10000");

        bytes32 txHash = keccak256(
            abi.encodePacked(
                "setDistribution",
                keccak256(abi.encode(accounts, bpsValues)),
                actionNonce["setDistribution"]
            )
        );
        if (confirmServers(txHash, "setDistribution")) {
            delete recipients;
            for (uint256 i = 0; i < len; i++) {
                recipients.push(Recipient(accounts[i], bpsValues[i], labels[i]));
            }
            emit DistributionUpdated(len);
        }
    }

    function pause() public onlyServers {
        bytes32 txHash = keccak256(abi.encodePacked("pause", actionNonce["pause"]));
        if (confirmServers(txHash, "pause")) {
            _pause();
        }
    }

    function unpause() public onlyServers {
        bytes32 txHash = keccak256(abi.encodePacked("unpause", actionNonce["unpause"]));
        if (confirmServers(txHash, "unpause")) {
            _unpause();
        }
    }

    // --- LECTURA DE TOKENOMICS ---

    function getRecipientsCount() external view returns (uint256) {
        return recipients.length;
    }

    function getAllRecipients() external view returns (Recipient[] memory) {
        return recipients;
    }

    // --- LÓGICA CENTRAL DE DISTRIBUCIÓN ---

    /**
     * @notice Recibe una cantidad de tokens de ingreso y la reparte según el array
     * `recipients` vigente, 100% definido por el multisig vía setDistribution().
     * @dev Asume que los tokens de ingreso ya han sido transferidos al PaymentRouter,
     * usualmente desde el FeeSplitter o directamente por el Admin.
     */
    function distributeRevenue(uint256 incomeAmount) public whenNotPaused {
        require(msg.sender == linealLiquidity, "PaymentRouter: Only authorized FeeSplitter");
        require(INCOME_TOKEN.balanceOf(address(this)) >= incomeAmount, "Insufficient income balance");

        uint256 len = recipients.length;
        for (uint256 i = 0; i < len; i++) {
            Recipient memory r = recipients[i];
            uint256 amount = (incomeAmount * r.bps) / BPS_DENOMINATOR;
            if (amount == 0) continue;
            INCOME_TOKEN.transfer(r.account, amount);
            emit RecipientPaid(i, r.account, amount);
        }

        emit RevenueDistributed(incomeAmount, len);
    }

    receive() external payable {}
}

project/contracts/economy/token/LinealTo.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.30;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "../../governance/LinealQorum.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title LinealToken - NeoQuor
 * @notice Stablecoin regulada respaldada 1:1 moneda FIAT
 *
 * CUMPLIMIENTO REGULATORIO Y COMPLIANCE:
 * - Gobernanza MultiSig de 3 capas integrada con LinealQorum
 * - Sistema KYC/AML mediante Whitelist y Blacklist
 * - Pausabilidad de emergencia
 * - Límites de transacción diaria para transferencia, mint y burn
 * - Recuperación de fondos por fraude comprobado u orden judicial
 * - Trazabilidad y auditoría on-chain (MintRecord / BurnRecord)
 */
contract LinealToken is ERC20, LinealQorum, Pausable {
    address public reserveBank;
    address public linealLiquidityAddress;
    bool public launched = false;

    bool public seedLaunched;

    // === COMPLIANCE & REGULATORY ===

    mapping(address => bool) public isWhitelisted;
    mapping(address => bool) public isBlacklisted;

    uint256 public dailyTransferLimit = 27_000_000 * 10**18; // 10M CLP
    uint256 public dailyMintLimit = 100_000_000 * 10**18;    // 100M CLP
    uint256 public dailyBurnLimit = 100_000_000 * 10**18;    // 100M CLP

    struct DailyVolume {
        uint256 date;
        uint256 minted;
        uint256 burned;
        mapping(address => uint256) transferred;
    }

    mapping(uint256 => DailyVolume) private _dailyVolumes;

    // === AUDIT TRAIL ===

    struct MintRecord {
        address to;
        uint256 amount;
        uint256 timestamp;
        address authorizedBy;
    }

    struct BurnRecord {
        address from;
        uint256 amount;
        uint256 timestamp;
        address authorizedBy;
    }

    MintRecord[] public mintHistory;
    BurnRecord[] public burnHistory;

    // === EVENTS ===

    event Minted(address indexed to, uint256 amount, address indexed authorizedBy, uint256 timestamp);
    event Burned(address indexed from, uint256 amount,address indexed authorizedBy, uint256 timestamp);
    event ReserveBankSet(address indexed newReserveBank);
    event AddressWhitelisted(address indexed account, bool status);
    event AddressBlacklisted(address indexed account, bool status);
    event DailyLimitsUpdated(uint256 transferLimit, uint256 mintLimit, uint256 burnLimit);
    event FundsRecovered(address indexed from, address indexed to, uint256 amount, string reason);


    constructor(
        string memory name,
        string memory symbol,
        address[] memory _machines,
        address[] memory _institutions,
        address[] memory _humans,
        uint256 _requiredMachines,
        uint256 _requiredInstitutions,
        uint256 _requiredHumans,
        uint256 _recoveryQuorum
    ) LinealQorum(_machines, _requiredMachines, _institutions, _requiredInstitutions, _humans, _requiredHumans, _recoveryQuorum)
    ERC20(name, symbol) {

    }

    // === MODIFIERS ===

    modifier onlyWhitelisted(address account) {
        require(isWhitelisted[account], "CLP: Address not whitelisted (KYC required)");
        _;
    }

    modifier notBlacklisted(address account) {
        require(!isBlacklisted[account], "CLP: Address is blacklisted");
        _;
    }

    // === EMERGENCY CONTROLS ===

    function pause() external onlyQorum {
        bytes32 txHash = _computeActionHash("pause",
            abi.encode(""));
        if (!confirm(txHash, "pause")) return;
        _pause();
    }

    function unpause() external onlyQorum {
        bytes32 txHash = _computeActionHash("unpause",
            abi.encode(""));
        if (!confirm(txHash, "unpause")) return;
        _unpause();
    }

    // === COMPLIANCE MANAGEMENT ===

    function setWhitelist(address account, bool status) external onlyServers {
        bytes32 txHash = _computeActionHash("setWhitelist",
            abi.encode(account, status));
        if (!confirmServers(txHash, "setWhitelist")) return;
        isWhitelisted[account] = status;
        emit AddressWhitelisted(account, status);
    }

    function setBlacklist(address account, bool status) external onlyServers {
        bytes32 txHash = _computeActionHash("setBlacklist",
            abi.encode(account, status));
        if (!confirmServers(txHash, "setBlacklist")) return;
        isBlacklisted[account] = status;
        emit AddressBlacklisted(account, status);
    }

    function launchPreSeed(address _linealLiquidity, uint256 totalAmount) external onlyServers {
        bytes32 txHash = _computeActionHash("launchPreSeed",
            abi.encode(_linealLiquidity, totalAmount));
        if (!confirmServers(txHash, "launchPreSeed")) return;
        require(linealLiquidityAddress == address(0), "Already Launched");
        isWhitelisted[_linealLiquidity] = true;
        linealLiquidityAddress = _linealLiquidity;
        _mint(_linealLiquidity, totalAmount * 1e18);
        emit AddressWhitelisted(_linealLiquidity, true);
    }

    function launchSeed(address _linealLiquidity, uint256 totalAmount) external onlyServers {
        require(launched == false, "Already Launched");
        bytes32 txHash = _computeActionHash("launchSeed",
            abi.encode(_linealLiquidity, totalAmount));
        if (!confirmServers(txHash, "launchSeed")) return;
        launched = true;
        _mint(_linealLiquidity, totalAmount * 1e18);
        emit AddressWhitelisted(_linealLiquidity, true);
    }

    function setDailyLimits(
        uint256 _transferLimit,
        uint256 _mintLimit,
        uint256 _burnLimit
    ) external onlyServers {
        bytes32 txHash = _computeActionHash("setDailyLimits",
            abi.encode(_transferLimit, _mintLimit, _burnLimit));
        if (!confirmServers(txHash, "setDailyLimits")) return;
        dailyTransferLimit = _transferLimit;
        dailyMintLimit = _mintLimit;
        dailyBurnLimit = _burnLimit;
        emit DailyLimitsUpdated(_transferLimit, _mintLimit, _burnLimit);
    }

    // === RESERVE BANK MANAGEMENT ===

    function setReserveBank(address _reserveBank) external onlyServers {
        require(reserveBank == address(0), "CLP: Reserve bank already set");
        require(_reserveBank != address(0), "CLP: Invalid reserve bank address");

        bytes32 txHash = _computeActionHash("setReserveBank",
            abi.encode(_reserveBank));
        if (!confirmServers(txHash, "setReserveBank")) return;
        reserveBank = _reserveBank;
        isWhitelisted[_reserveBank] = true;
        emit ReserveBankSet(_reserveBank);
    }

    // === MINT & BURN (BACKED BY FIAT) ===

    function mint(
        address to,
        uint256 amount
    ) external whenNotPaused onlyWhitelisted(to) notBlacklisted(to) {
        require(reserveBank != address(0), "CLP: Bank not linked");
        require(msg.sender == linealLiquidityAddress, "CLP: Sender is not Authorized Bank");
        require(to != address(0), "CLP: Invalid recipient");
        require(amount > 0, "CLP: Amount must be > 0");

        uint256 today = block.timestamp / 1 days;
        DailyVolume storage volume = _dailyVolumes[today];
        if (volume.date != today) {
            volume.date = today;
            volume.minted = 0;
        }
        require(volume.minted + amount <= dailyMintLimit, "CLP: Daily mint limit exceeded");

        volume.minted += amount;

        mintHistory.push(MintRecord({
            to: to,
            amount: amount,
            timestamp: block.timestamp,
            authorizedBy: msg.sender
        }));

        _mint(to, amount);
        emit Minted(to, amount, msg.sender, block.timestamp);
    }

    function burn(
        address from,
        uint256 amount
    ) external whenNotPaused notBlacklisted(from) {
        require(reserveBank != address(0), "CLP: Reserve bank not set");
        require(msg.sender == linealLiquidityAddress, "CLP: Sender is not Authorized Bank");
        require(from != address(0), "CLP: Invalid address");
        require(amount > 0, "CLP: Amount must be > 0");
        require(balanceOf(from) >= amount, "CLP: Insufficient balance");

        uint256 today = block.timestamp / 1 days;
        DailyVolume storage volume = _dailyVolumes[today];
        if (volume.date != today) {
            volume.date = today;
            volume.burned = 0;
        }
        require(volume.burned + amount <= dailyBurnLimit, "CLP: Daily burn limit exceeded");

        volume.burned += amount;

        burnHistory.push(BurnRecord({
            from: from,
            amount: amount,
            timestamp: block.timestamp,
            authorizedBy: msg.sender
        }));

        _burn(from, amount);
        emit Burned(from, amount, msg.sender, block.timestamp);
    }

    // === FRAUD RECOVERY ===

    function recoverFunds(
        address from,
        address to,
        uint256 amount,
        string memory reason
    ) external whenNotPaused {
        require(from != address(0) && to != address(0), "CLP: Invalid addresses");
        require(msg.sender == reserveBank, "CLP: Sender is not Authorized Bank");
        require(amount > 0 && balanceOf(from) >= amount, "CLP: Invalid amount");
        require(isWhitelisted[to], "CLP: Recipient must be whitelisted");
        _transfer(from, to, amount);
        emit FundsRecovered(from, to, amount, reason);
    }

    // === OVERRIDES FOR COMPLIANCE ===

    function transfer(address to, uint256 amount)
    public
    override
    whenNotPaused
    onlyWhitelisted(msg.sender)
    onlyWhitelisted(to)
    notBlacklisted(msg.sender)
    notBlacklisted(to)
    returns (bool)
    {
        _checkAndRecordDailyTransfer(msg.sender, amount);
        return super.transfer(to, amount);
    }

    function transferFrom(address from, address to, uint256 amount)
    public
    override
    whenNotPaused
    onlyWhitelisted(from)
    onlyWhitelisted(to)
    notBlacklisted(from)
    notBlacklisted(to)
    returns (bool)
    {
        _checkAndRecordDailyTransfer(from, amount);
        return super.transferFrom(from, to, amount);
    }

    function _checkAndRecordDailyTransfer(address account, uint256 amount) internal {
        uint256 today = block.timestamp / 1 days;
        DailyVolume storage volume = _dailyVolumes[today];

        if (volume.date != today) {
            volume.date = today;
        }

        require(
            volume.transferred[account] + amount <= dailyTransferLimit,
            "CLP: Daily transfer limit exceeded"
        );

        volume.transferred[account] += amount;
    }

    // === VIEW FUNCTIONS ===

    function getCirculatingSupply() external view returns (uint256) {
        return totalSupply();
    }

    function getMintHistoryLength() external view returns (uint256) {
        return mintHistory.length;
    }

    function getBurnHistoryLength() external view returns (uint256) {
        return burnHistory.length;
    }

    function getDailyTransferVolume(address account) external view returns (uint256) {
        uint256 today = block.timestamp / 1 days;
        DailyVolume storage volume = _dailyVolumes[today];
        return volume.date == today ? volume.transferred[account] : 0;
    }

    function getDailyMintBurnVolume() external view returns (uint256 minted, uint256 burned) {
        uint256 today = block.timestamp / 1 days;
        DailyVolume storage volume = _dailyVolumes[today];
        if (volume.date == today) {
            return (volume.minted, volume.burned);
        }
        return (0, 0);
    }
}

project/contracts/governance/LinealQorum.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.30;

abstract contract LinealQorum {
    // 1 = Machine, 2 = Institution, 3 = Human
    mapping(address => uint8) public signerType;

    address[] public machines;
    address[] public institutions;
    address[] public humans;

    uint256 public requiredMachines;
    uint256 public requiredInstitutions;
    uint256 public requiredHumans;

    address public guardian;
    address public identityContract;

    mapping(bytes32 => mapping(address => bool)) public isConfirmed;
    mapping(bytes32 => uint256) public confirmationCount;
    mapping(bytes32 => bool) public isExecuted;

    mapping(bytes32 => uint256) public machineConfirmations;
    mapping(bytes32 => uint256) public institutionConfirmations;
    mapping(bytes32 => uint256) public humanConfirmations;

    mapping(string => uint256) public actionNonce;

    uint256 public recoveryQuorum;
    uint256 public constant RECOVERY_DELAY = 2 hours;

    struct RecoveryProposal {
        address[] newMachines;
        address[] newInstitutions;
        address[] newHumans;
        uint256 newRequiredMachines;
        uint256 newRequiredInstitutions;
        uint256 newRequiredHumans;
        uint256 proposedAt;
        uint256 confirmations;
        bool executed;
        mapping(address => bool) confirmedBy;
    }

    mapping(bytes32 => RecoveryProposal) private _recoveryProposals;

    event ActionProposed(bytes32 indexed txHash, address indexed proposer, string actionType);
    event ActionConfirmed(bytes32 indexed txHash, address indexed signer);
    event ActionExecuted(bytes32 indexed txHash);
    event GuardianUpdated(address indexed newGuardian);
    event QuantumCommitmentUpdated(address indexed signer, bytes32 commitment);
    event RecoveryProposed(bytes32 indexed recoveryHash, address indexed proposer);
    event RecoveryConfirmed(bytes32 indexed recoveryHash, address indexed confirmer, uint256 confirmations);
    event RecoveryExecuted(bytes32 indexed recoveryHash);

    modifier onlyQorum() {
        require(signerType[msg.sender] != 0, "LQ: not signer");
        _;
    }

    modifier onlyServers() {
        uint8 sType = signerType[msg.sender];
        require(sType == 1 || sType == 2, "LQ: not a server layer");
        _;
    }

    modifier onlyGuardian() {
        require(msg.sender == guardian, "LQ: only guardian");
        _;
    }

    constructor(
        address[] memory _qorumServers,
        uint256 _requiredQorumServers,
        address[] memory _institutionsServers,
        uint256 _requiredInstitutionsServers,
        address[] memory _operators,
        uint256 _requiredOperators,
        uint256 _recoveryQuorum
    ) {
        require(_requiredQorumServers > 0 && _qorumServers.length >= _requiredQorumServers, "LQ: invalid machines req");
        require(_requiredInstitutionsServers > 0 && _institutionsServers.length >= _requiredInstitutionsServers, "LQ: invalid inst req");
        require(_recoveryQuorum > 0, "LQ: invalid recovery quorum");

        requiredMachines = _requiredQorumServers;
        requiredInstitutions = _requiredInstitutionsServers;
        recoveryQuorum = _recoveryQuorum;

        if (_operators.length > 0) {
            require(_requiredOperators > 0 && _operators.length >= _requiredOperators, "LQ: invalid humans req");
            requiredHumans = _requiredOperators;
        }

        _addSigners(_qorumServers, 1, machines);
        _addSigners(_institutionsServers, 2, institutions);
        _addSigners(_operators, 3, humans);
    }

    function proposeRecovery(
        address[] memory _newMachines,
        uint256 _newRequiredMachines,
        address[] memory _newInstitutions,
        uint256 _newRequiredInstitutions,
        address[] memory _newHumans,
        uint256 _newRequiredHumans
    ) external onlyQorum returns (bytes32 recoveryHash) {
        require(_newRequiredMachines > 0 && _newMachines.length >= _newRequiredMachines, "LQ: invalid machines");
        require(_newRequiredInstitutions > 0 && _newInstitutions.length >= _newRequiredInstitutions, "LQ: invalid inst");
        require(_newRequiredHumans > 0 && _newHumans.length >= _newRequiredHumans, "LQ: invalid humans");

        _validateAddresses(_newMachines);
        _validateAddresses(_newInstitutions);
        _validateAddresses(_newHumans);

        recoveryHash = keccak256(abi.encode(
            _newMachines,
            _newRequiredMachines,
            _newInstitutions,
            _newRequiredInstitutions,
            _newHumans,
            _newRequiredHumans,
            address(this),
            block.chainid
        ));

        RecoveryProposal storage proposal = _recoveryProposals[recoveryHash];
        require(proposal.proposedAt == 0, "LQ: proposal exists");

        proposal.newMachines = _newMachines;
        proposal.newInstitutions = _newInstitutions;
        proposal.newHumans = _newHumans;
        proposal.newRequiredMachines = _newRequiredMachines;
        proposal.newRequiredInstitutions = _newRequiredInstitutions;
        proposal.newRequiredHumans = _newRequiredHumans;
        proposal.proposedAt = block.timestamp;
        proposal.confirmations = 1;
        proposal.confirmedBy[msg.sender] = true;

        emit RecoveryProposed(recoveryHash, msg.sender);
        emit RecoveryConfirmed(recoveryHash, msg.sender, 1);
    }

    function confirmRecovery(bytes32 recoveryHash) external onlyQorum {
        RecoveryProposal storage proposal = _recoveryProposals[recoveryHash];
        require(proposal.proposedAt != 0, "LQ: proposal not found");
        require(!proposal.executed, "LQ: already executed");
        require(!proposal.confirmedBy[msg.sender], "LQ: already confirmed");

        proposal.confirmedBy[msg.sender] = true;
        proposal.confirmations++;

        emit RecoveryConfirmed(recoveryHash, msg.sender, proposal.confirmations);
    }

    function executeRecovery(bytes32 recoveryHash) external onlyQorum {
        RecoveryProposal storage proposal = _recoveryProposals[recoveryHash];
        require(proposal.proposedAt != 0, "LQ: not found");
        require(!proposal.executed, "LQ: already executed");
        require(proposal.confirmations >= recoveryQuorum, "LQ: insufficient confirmations");
        require(block.timestamp >= proposal.proposedAt + RECOVERY_DELAY, "LQ: delay not passed");

        proposal.executed = true;

        _clearSigners(machines);
        _clearSigners(institutions);
        _clearSigners(humans);

        _addSigners(proposal.newMachines, 1, machines);
        _addSigners(proposal.newInstitutions, 2, institutions);
        _addSigners(proposal.newHumans, 3, humans);

        requiredMachines = proposal.newRequiredMachines;
        requiredInstitutions = proposal.newRequiredInstitutions;
        requiredHumans = proposal.newRequiredHumans;

        emit RecoveryExecuted(recoveryHash);
    }

    function setGuardian(address _newGuardian) external virtual onlyQorum {
        require(_newGuardian != address(0), "LQ: invalid guardian");
        guardian = _newGuardian;
        emit GuardianUpdated(_newGuardian);
    }


    function confirmServers(
        bytes32 txHash,
        string memory actionType
    ) internal returns (bool) {
        require(!isExecuted[txHash], "LQ: already executed");
        uint8 sType = signerType[msg.sender];
        require(sType == 1 || sType == 2, "LQ: not a server layer");
        require(!isConfirmed[txHash][msg.sender], "LQ: already confirmed");

        isConfirmed[txHash][msg.sender] = true;

        if (sType == 1) {
            machineConfirmations[txHash]++;
        } else {
            institutionConfirmations[txHash]++;
        }

        if (confirmationCount[txHash] == 0) {
            emit ActionProposed(txHash, msg.sender, actionType);
        }

        confirmationCount[txHash]++;
        emit ActionConfirmed(txHash, msg.sender);

        if (
            machineConfirmations[txHash] >= requiredMachines &&
            institutionConfirmations[txHash] >= requiredInstitutions
        ) {
            isExecuted[txHash] = true;
            actionNonce[actionType]++;
            emit ActionExecuted(txHash);
            return true;
        }

        return false;
    }

    function confirm(
        bytes32 txHash,
        string memory actionType
    ) internal returns (bool) {
        require(!isExecuted[txHash], "LQ: already executed");
        require(signerType[msg.sender] != 0, "LQ: invalid signer");
        require(!isConfirmed[txHash][msg.sender], "LQ: already confirmed");

        isConfirmed[txHash][msg.sender] = true;
        uint8 sType = signerType[msg.sender];

        if (sType == 1) {
            machineConfirmations[txHash]++;
        } else if (sType == 2) {
            institutionConfirmations[txHash]++;
        } else if (sType == 3) {
            humanConfirmations[txHash]++;
        }

        if (confirmationCount[txHash] == 0) {
            emit ActionProposed(txHash, msg.sender, actionType);
        }

        confirmationCount[txHash]++;
        emit ActionConfirmed(txHash, msg.sender);

        if (
            machineConfirmations[txHash] >= requiredMachines &&
            institutionConfirmations[txHash] >= requiredInstitutions &&
            humanConfirmations[txHash] >= requiredHumans
        ) {
            isExecuted[txHash] = true;
            actionNonce[actionType]++;
            emit ActionExecuted(txHash);
            return true;
        }

        return false;
    }

    function _computeActionHash(
        string memory actionType,
        bytes memory params
    ) internal view returns (bytes32) {
        return keccak256(abi.encode(
            keccak256(bytes(actionType)),
            address(this),
            block.chainid,
            keccak256(params),
            actionNonce[actionType]
        ));
    }

    function _isSigner(address account) public view returns (bool) {
        return signerType[account] != 0;
    }

    function _isMachine(address account) internal view returns (bool) {
        return signerType[account] == 1;
    }

    function _isInstitution(address account) internal view returns (bool) {
        return signerType[account] == 2;
    }

    function _isHuman(address account) internal view returns (bool) {
        return signerType[account] == 3;
    }

    function _addSigners(address[] memory accounts, uint8 typeId, address[] storage storageArray) private {
        for (uint256 i = 0; i < accounts.length; i++) {
            address acc = accounts[i];
            require(acc != address(0), "LQ: zero address");
            require(signerType[acc] == 0, "LQ: duplicate signer");
            signerType[acc] = typeId;
            storageArray.push(acc);
        }
    }

    function _clearSigners(address[] storage storageArray) private {
        for (uint256 i = 0; i < storageArray.length; i++) {
            signerType[storageArray[i]] = 0;
        }
        uint256 len = storageArray.length;
        for (uint256 i = 0; i < len; i++) {
            storageArray.pop();
        }
    }

    function _validateAddresses(address[] memory accounts) private pure {
        for (uint256 i = 0; i < accounts.length; i++) {
            require(accounts[i] != address(0), "LQ: zero address proposed");
        }
    }
}

project/contracts/institution/LinealCiti.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.30;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Base64.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

contract LinealCitizens is ERC721, Ownable {
    using Strings for uint256;

    // ───────────── Constantes ─────────────

    uint256 public constant MAX_SCORE = 10000;
    uint256 public constant MIN_DELTA = 1;
    uint256 public constant MAX_DELTA = 10000;

    // ───────────── Identidad y reputación ─────────────

    uint256 public tokenCounter;

    // Permite encontrar el NFT de una wallet.
    mapping(address => uint256) public walletToToken;

    // Los nombres de usuario son únicos dentro de esta institución.
    mapping(string => bool) public usernameTaken;

    struct Profile {
        uint256 tokenId;
        string username;
        string imageURI;
        bytes32 subAccountId;
        uint256 reputation;
        bool exists;
    }

    // La identidad y su reputación pertenecen al mismo NFT.
    mapping(uint256 => Profile) private profiles;

    // Estadísticas agregadas de todos los perfiles.
    uint256 public totalGlobalScore;
    uint256 public totalWallets;

    // ───────────── Eventos ─────────────

    event ProfileIssued(
        address indexed wallet,
        uint256 indexed tokenId,
        string username,
        bytes32 subAccountId
    );

    event ProfileImageUpdated(
        address indexed wallet,
        string newImageURI
    );

    event ScoreUpdated(
        address indexed wallet,
        uint256 indexed tokenId,
        uint256 oldScore,
        uint256 newScore
    );

    // ───────────── Constructor ─────────────

    constructor(
        string memory identityName,
        string memory identitySymbol,
        address institutionOwner
    )
    ERC721(identityName, identitySymbol)
    Ownable(institutionOwner)
    {
        require(
            institutionOwner != address(0),
            "Invalid institution owner"
        );
    }

    // ───────────── Crear perfil NFT ─────────────

    function mintProfile(
        address wallet,
        string calldata username,
        string calldata imageURI,
        bytes32 subAccountId
    ) external onlyOwner returns (uint256) {
        require(wallet != address(0), "Invalid wallet");
        require(walletToToken[wallet] == 0, "Profile exists");
        require(bytes(username).length > 0, "Empty username");
        require(bytes(username).length <= 32, "Username too long");
        require(!usernameTaken[username], "Username taken");
        require(_validUsername(username), "Invalid username");
        require(_validImageURI(imageURI), "Invalid image URI");
        require(subAccountId != bytes32(0), "Invalid subaccount");

        tokenCounter++;
        uint256 tokenId = tokenCounter;

        usernameTaken[username] = true;
        walletToToken[wallet] = tokenId;

        profiles[tokenId] = Profile({
            tokenId: tokenId,
            username: username,
            imageURI: imageURI,
            subAccountId: subAccountId,
            reputation: 0,
            exists: true
        });

        // Cada NFT nuevo inicia con reputación cero.
        totalWallets++;

        _mint(wallet, tokenId);

        emit ProfileIssued(
            wallet,
            tokenId,
            username,
            subAccountId
        );

        return tokenId;
    }

    // ───────────── Actualizar imagen ─────────────

    function setImageURI(
        address wallet,
        string calldata newImageURI
    ) external onlyOwner {
        uint256 tokenId = walletToToken[wallet];

        require(tokenId != 0, "Profile not found");
        require(_validImageURI(newImageURI), "Invalid image URI");

        profiles[tokenId].imageURI = newImageURI;

        emit ProfileImageUpdated(wallet, newImageURI);
    }

    // ───────────── Consultar perfil ─────────────

    function getProfile(
        address wallet
    )
    external
    view
    returns (
        uint256 tokenId,
        string memory username,
        string memory imageURI,
        bytes32 subAccountId,
        uint256 reputation,
        string memory level
    )
    {
        tokenId = walletToToken[wallet];

        require(tokenId != 0, "Profile not found");

        Profile storage p = profiles[tokenId];

        return (
            p.tokenId,
            p.username,
            p.imageURI,
            p.subAccountId,
            p.reputation,
            _levelOf(p.reputation)
        );
    }

    function getProfileByToken(
        uint256 tokenId
    )
    external
    view
    returns (Profile memory profile, string memory level)
    {
        require(profiles[tokenId].exists, "Profile not found");

        profile = profiles[tokenId];
        level = _levelOf(profile.reputation);
    }

    function getTokenCounter() external view returns (uint256) {
        return tokenCounter;
    }

    // ───────────── Reputación del NFT ─────────────

    function updateScore(
        uint256 tokenId,
        uint256 delta,
        bool positive
    ) external onlyOwner {
        require(profiles[tokenId].exists, "Profile not found");
        require(
            delta >= MIN_DELTA && delta <= MAX_DELTA,
            "Invalid delta"
        );

        Profile storage p = profiles[tokenId];

        uint256 oldScore = p.reputation;
        uint256 newScore;

        if (positive) {
            // Evita desbordamiento y limita la reputación a 10000.
            if (delta >= MAX_SCORE - oldScore) {
                newScore = MAX_SCORE;
            } else {
                newScore = oldScore + delta;
            }
        } else {
            newScore = delta >= oldScore ? 0 : oldScore - delta;
        }

        p.reputation = newScore;

        totalGlobalScore =
            totalGlobalScore -
            oldScore +
            newScore;

        emit ScoreUpdated(
            ownerOf(tokenId),
            tokenId,
            oldScore,
            newScore
        );
    }

    function getReputation(
        uint256 tokenId
    )
    external
    view
    returns (
        uint256 overall,
        string memory level
    )
    {
        require(profiles[tokenId].exists, "Profile not found");

        overall = profiles[tokenId].reputation;
        level = _levelOf(overall);
    }

    function _levelOf(
        uint256 score
    ) internal view returns (string memory) {
        uint256 average = totalWallets == 0
            ? 0
            : totalGlobalScore / totalWallets;

        if (
            score >= 9500 ||
            (average > 0 && score >= average * 5)
        ) {
            return "Anomalia";
        }

        if (score >= 8000) return "Principal";
        if (score >= 6000) return "Agente";
        if (score >= 4000) return "Operador";
        if (score >= 2000) return "Jugador";

        return "Ciudadano";
    }

    // ───────────── NFT soulbound ─────────────

    function _update(
        address to,
        uint256 tokenId,
        address auth
    ) internal override returns (address) {
        address from = _ownerOf(tokenId);

        // Permite mintear, pero impide transferencias y quemados.
        if (from != address(0)) {
            revert("Identity is non-transferable");
        }

        return super._update(to, tokenId, auth);
    }

    // ───────────── Metadatos NFT ─────────────

    function tokenURI(
        uint256 tokenId
    ) public view override returns (string memory) {
        require(profiles[tokenId].exists, "Token not found");

        Profile storage p = profiles[tokenId];

        string memory json = string.concat(
            '{"name":"',
            _escapeJSON(p.username),
            '","description":"Lineal Identity",',
            '"image":"',
            _escapeJSON(p.imageURI),
            '","attributes":[',
            '{"trait_type":"Institution","value":"',
            Strings.toHexString(uint160(owner()), 20),
            '"},',
            '{"trait_type":"Account","value":"',
            Strings.toHexString(uint256(p.subAccountId), 32),
            '"},',
            '{"trait_type":"Reputation","value":',
            Strings.toString(p.reputation),
            '},',
            '{"trait_type":"Level","value":"',
            _levelOf(p.reputation),
            '"}]}'
        );

        return string.concat(
            "data:application/json;base64,",
            Base64.encode(bytes(json))
        );
    }


    function subAccountOf(address wallet) external view returns (bytes32) {
        uint256 tokenId = walletToToken[wallet];
        if (tokenId == 0) return bytes32(0);
        return profiles[tokenId].subAccountId;
    }
    // ───────────── Validaciones ─────────────

    function _validUsername(
        string calldata username
    ) internal pure returns (bool) {
        bytes calldata b = bytes(username);

        for (uint256 i; i < b.length; i++) {
            bytes1 c = b[i];

            bool valid =
                (c >= 0x41 && c <= 0x5A) ||
                (c >= 0x61 && c <= 0x7A) ||
                (c >= 0x30 && c <= 0x39) ||
                c == 0x5F ||
                c == 0x2D ||
                c == 0x2E;

            if (!valid) return false;
        }

        return true;
    }

    function _validImageURI(
        string calldata uri
    ) internal pure returns (bool) {
        bytes calldata b = bytes(uri);

        if (b.length == 0) return false;

        for (uint256 i; i < b.length; i++) {
            uint8 c = uint8(b[i]);

            // Evita caracteres de control. El JSON se escapa aparte.
            if (c < 0x20 || c == 0x7F) return false;
        }

        return true;
    }

    function _escapeJSON(
        string memory value
    ) internal pure returns (string memory) {
        bytes memory input = bytes(value);
        bytes memory output = new bytes(input.length * 2);
        uint256 j;

        for (uint256 i; i < input.length; i++) {
            bytes1 c = input[i];

            if (c == 0x22 || c == 0x5C) {
                output[j++] = 0x5C;
                output[j++] = c;
            } else if (uint8(c) < 0x20) {
                // Los caracteres de control no son necesarios
                // en username ni imageURI.
                output[j++] = 0x20;
            } else {
                output[j++] = c;
            }
        }

        bytes memory result = new bytes(j);

        for (uint256 i; i < j; i++) {
            result[i] = output[i];
        }

        return string(result);
    }
}

project/contracts/institution/LinealInst.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.30;

import "../governance/LinealQorum.sol";
import "../economy/banks/LinealBank.sol";
import "../economy/token/LinealToken.sol";
import "../institution/LinealTender.sol";
import "../institution/LinealCitizens.sol"; // ajusta la ruta a donde esté tu archivo
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title LinealInstitution - NeoQuor
 * @notice Contrato estándar que representa a una Institución/Corporación en el ecosistema.
 *         Su banco custodia varios tokens ERC20; los tokens habilitados se gestionan por quórum.
 */
contract LinealInstitution is LinealQorum {

    string public institutionName;
    string public description;
    address public linealIdentity;
    address public linealCoin; // token principal (el primero de la lista inicial), por compatibilidad
    address public institutionBank;
    address public institutionTender;
    address public stableCoin;
    bytes32 public rewardsAccountId;
    bytes32 public institutionAccountId;
    uint256 public constant CREATION_FEE = 1_000_000;
    mapping(bytes32 => bool) public activeSubAccounts;
    mapping(address => bool) public isDirectiva;
    bytes32[] public subAccountIds;
    address[] private _directiva;

    event RewardsAccountCreated(bytes32 indexed accountId);
    event DescriptionUpdated(string newDescription);
    event SubAccountCreated(bytes32 indexed accountId, string accountName);
    event FundsMovedToSubAccount(
        bytes32 indexed fromAccount,
        bytes32 indexed toAccount,
        address indexed token,
        uint256 amount
    );
    event FundsMovedToBank(
        bytes32 indexed fromAccount,
        address indexed destBank,
        bytes32 indexed toAccount,
        address token,
        uint256 amount
    );
    event FundsReleased(
        bytes32 indexed accountId,
        address indexed to,
        address indexed token,
        uint256 amount,
        bytes32 reason
    );
    event PreFundsReleased(
        bytes32 indexed accountId,
        address indexed to,
        address indexed token,
        uint256 amount
    );
    event TokenSupportSet(address indexed token, bool supported);
    event BankLinked(address indexed bankAddress);
    event TendersLinked(address indexed tendersAddress);
    event IdentityLinked(address indexed identityAddress);
    event ProfileIssued(address indexed wallet, string username, string imageURI);
    event CitizenAccountCreated(address indexed wallet, bytes32 indexed accountId);
    event ProfileImageUpdated(address indexed wallet, string newImageURI);
    event TenderIssued(uint256 indexed tokenId, string title, string documentURL);
    event PaymentProcessed(address indexed wallet, uint256 amount);
    event TenderAccountCreated(uint256 indexed tokenId, bytes32 indexed accountId);
    event InstitutionAccountCreated(bytes32 indexed accountId, string accountName);

    error MintFailed();
    error PaymentFailed();
    error BankNotLinked();
    error TendersNotLinked();
    error InvalidSubAccount();
    error InvalidDestBank();
    error InvalidToken();

    constructor(
        address _stableCoin,
        uint256 _bps,
        string memory _institutionName,
        string memory _description,
        address[] memory _machines,
        address[] memory _institutions,
        address[] memory _humans,
        uint256 _requiredMachines,
        uint256 _requiredInstitutions,
        uint256 _requiredHumans,
        uint256 _recoveryQuorum
    ) LinealQorum(
    _machines,
    _requiredMachines,
    _institutions,
    _requiredInstitutions,
    _humans,
    _requiredHumans,
    _recoveryQuorum
    ) {
        institutionName = _institutionName;
        description = _description;
        stableCoin = _stableCoin;
        // La directiva son los humans definidos
        for (uint256 i; i < _humans.length; i++) {
            address h = _humans[i];
            if (h != address(0) && !isDirectiva[h]) {
                isDirectiva[h] = true;
                _directiva.push(h);
            }
        }

        // Banco: esta Institución es su owner. _bps = fee de rewards por transferencia interna.
        LinealBank bank = new LinealBank(address(this), _bps);
        institutionBank = address(bank);

        // La subcuenta "Rewards" la crea el banco en su constructor: se registra aquí también.
        bytes32 rewardsId = bank.rewardsAccountId();
        rewardsAccountId = rewardsId;
        activeSubAccounts[rewardsId] = true;
        subAccountIds.push(rewardsId);
        // Cuenta propia de la institución
        bytes32 instId = bank.createSubAccount(_institutionName);
        institutionAccountId = instId;
        activeSubAccounts[instId] = true;
        subAccountIds.push(instId);
        emit InstitutionAccountCreated(instId, _institutionName);
        emit BankLinked(institutionBank);

        // Licitaciones (NFT): esta Institución es su owner
        institutionTender = address(
            new LinealTender(
                string.concat(_institutionName, " Tenders"),
                "TENDER",
                address(this)
            )
        );
        LinealBank(institutionBank).setTokenSupport(_stableCoin, true);
        emit TendersLinked(institutionTender);
    }

    // ───────────── Tokens soportados por el banco ─────────────

    /**
     * @notice Habilita o deshabilita depósitos de un token en el banco. Requiere quórum.
     * @dev Deshabilitar no bloquea retiros ni transferencias de saldos existentes.
     */
    function setTokenSupport(address token, bool supported) external onlyServers {
        if (institutionBank == address(0)) revert BankNotLinked();
        if (token == address(0)) revert InvalidToken();

        bytes32 txHash = _computeActionHash("setTokenSupport", abi.encode(token, supported));
        if (!confirmServers(txHash, "setTokenSupport")) return;

        LinealBank(institutionBank).setTokenSupport(token, supported);
        emit TokenSupportSet(token, supported);
    }

    function setPairToken(address token) external onlyServers {
        if (institutionBank == address(0)) revert BankNotLinked();
        if (token == address(0)) revert InvalidToken();

        {
            bytes32 txHash = _computeActionHash("setPairToken", abi.encode(token));
            if (!confirmServers(txHash, "setPairToken")) return;
        }
        LinealBank(institutionBank).setTokenSupport(token, true);
        linealCoin = token;
        emit TokenSupportSet(token, true);
    }

    function setCitizensAddress(address contractAddress) external onlyServers {
        if (contractAddress == address(0)) revert InvalidToken();
        bytes32 txHash = _computeActionHash("setCitizensAddress", abi.encode(contractAddress));
        if (!confirmServers(txHash, "setCitizensAddress")) return;
        linealIdentity = contractAddress;
        emit IdentityLinked(contractAddress);
    }

    /**
     * @notice Crea una nueva subcuenta asociada a esta Institución. Requiere quorum de signers.
     * @param accountName Nombre de la subcuenta.
     */
    function createSubAccount(string calldata accountName) external onlyQorum {
        if (institutionBank == address(0)) revert BankNotLinked();

        bytes32 txHash = _computeActionHash("createSubAccount", abi.encode(accountName));
        if (!confirm(txHash, "createSubAccount")) return;

        bytes32 id = LinealBank(institutionBank).createSubAccount(accountName);
        activeSubAccounts[id] = true;
        subAccountIds.push(id);
        emit SubAccountCreated(id, accountName);
    }

    /**
     * @notice Mueve un token entre dos subcuentas del banco de esta Institución. Requiere quórum.
     */
    function moveFundsToSubAccount(
        bytes32 fromAccount,
        bytes32 toAccount,
        address token,
        uint256 amount
    ) external onlyQorum {
        if (institutionBank == address(0)) revert BankNotLinked();
        if (!activeSubAccounts[fromAccount]) revert InvalidSubAccount();
        if (!activeSubAccounts[toAccount]) revert InvalidSubAccount();

        bytes32 txHash = _computeActionHash(
            "moveFundsToSubAccount",
            abi.encode(fromAccount, toAccount, token, amount)
        );
        if (!confirm(txHash, "moveFundsToSubAccount")) return;

        LinealBank(institutionBank).internalTransfer(fromAccount, toAccount, token, amount);
        emit FundsMovedToSubAccount(fromAccount, toAccount, token, amount);
    }

    /**
     * @notice Envía un token de una subcuenta del banco de esta Institución a una subcuenta
     *         del banco de OTRA institución. Requiere quórum de signers.
     * @dev El banco destino debe tener habilitado ese token (lo valida el banco).
     *      `toAccount` pertenece al banco destino, por eso no se valida contra `activeSubAccounts`.
     * @param fromAccount Subcuenta de origen en el banco de esta Institución.
     * @param destBank    Dirección del LinealBank destino.
     * @param toAccount   Subcuenta de destino en `destBank`.
     * @param token       Token a enviar.
     * @param amount      Monto bruto a debitar (el banco descuenta el fee de rewards).
     */
    function moveFundsToBank(
        bytes32 fromAccount,
        address destBank,
        bytes32 toAccount,
        address token,
        uint256 amount
    ) external onlyQorum {
        if (institutionBank == address(0)) revert BankNotLinked();
        if (!activeSubAccounts[fromAccount]) revert InvalidSubAccount();
        if (destBank == address(0) || destBank == institutionBank) revert InvalidDestBank();

        bytes32 txHash = _computeActionHash(
            "moveFundsToBank",
            abi.encode(fromAccount, destBank, toAccount, token, amount)
        );
        if (!confirm(txHash, "moveFundsToBank")) return;

        LinealBank(institutionBank).transferToBank(fromAccount, destBank, toAccount, token, amount);
        emit FundsMovedToBank(fromAccount, destBank, toAccount, token, amount);
    }

    /**
     * @notice Libera un token de una subcuenta del banco hacia una dirección externa. Requiere quórum.
     */
    function releaseFromBank(
        bytes32 accountId,
        address token,
        address payable to,
        uint256 amount,
        bytes32 reason
    ) external onlyQorum {
        if (institutionBank == address(0)) revert BankNotLinked();
        if (!activeSubAccounts[accountId]) revert InvalidSubAccount();

        bytes32 txHash = _computeActionHash(
            "releaseFromBank",
            abi.encode(accountId, token, to, amount, reason)
        );
        if (!confirm(txHash, "releaseFromBank")) return;

        LinealBank(institutionBank).release(accountId, token, to, amount, reason);
        emit FundsReleased(accountId, to, token, amount, reason);
    }


    /**
     * @notice Libera un token de una subcuenta del banco hacia una dirección externa. Requiere quórum.
     */
    function releasePreSale(
        address token,
        address payable to,
        uint256 amount
    ) external onlyServers {
        if (institutionBank == address(0)) revert BankNotLinked();

        bytes32 txHash = _computeActionHash(
            "releasePreSale",
            abi.encode(token, to, amount)
        );
        if (!confirm(txHash, "releasePreSale")) return;
        bytes32 citizenAccountId = LinealCitizens(linealIdentity).subAccountOf(to);
        LinealBank(institutionBank).internalTransfer(institutionAccountId, citizenAccountId, token,  amount);
        emit PreFundsReleased(institutionAccountId, to, token, amount);
    }

    // ───────────── Licitaciones (LinealTenders) ─────────────

    function mintTender(
        string calldata title,
        string calldata tenderDescription,
        string calldata imageURI,
        string calldata documentURL,
        uint256 amount
    ) external onlyQorum {
        if (institutionTender == address(0)) revert TendersNotLinked();
        if (institutionBank == address(0)) revert BankNotLinked();

        {
            bytes32 txHash = _computeActionHash(
                "mintTender",
                abi.encode(title, tenderDescription, imageURI, documentURL, amount)
            );
            if (!confirm(txHash, "mintTender")) return;
        }

        // 1. Crear la subcuenta de la licitación en el banco
        bytes32 id = LinealBank(institutionBank).createSubAccount(title);
        activeSubAccounts[id] = true;
        subAccountIds.push(id);

        // 2. Mintear la licitación pasando la subcuenta como argumento
        uint256 tokenId = LinealTender(institutionTender).mintTender(
            title,
            tenderDescription,
            imageURI,
            documentURL,
            amount,
            id
        );

        emit TenderIssued(tokenId, title, documentURL);
        emit TenderAccountCreated(tokenId, id);
    }

    // ───────────── Identidad (LinealCitizens) ─────────────

    /**
     * @notice Emite un perfil soulbound en LinealCitizens. Requiere quórum de servers.
     *         Primero crea la subcuenta del ciudadano en el banco y luego mintea el perfil
     *         pasando el id de la subcuenta. La recompensa de 5 QRM sale del saldo de LinealCitizens.
     */
    function mintProfile(
        address wallet,
        string calldata username,
        string calldata imageURI
    ) external onlyServers {
        {
            bytes32 txHash = _computeActionHash(
                "mintProfile",
                abi.encode(wallet, username, imageURI)
            );
            if (!confirmServers(txHash, "mintProfile")) return;
        }
        uint256 tokenCounter = LinealCitizens(linealIdentity).tokenCounter();

        bytes32 id = LinealBank(institutionBank).createCitizenAccount(username);
        activeSubAccounts[id] = true;
        subAccountIds.push(id);

        if ((tokenCounter + 1) <= 25000) {
            LinealBank(institutionBank).zeroFeeInternalTransfer(institutionAccountId, id, linealCoin, 50 * 1e18);
        }

        // 2. Mintear el perfil pasando la subcuenta como argumento
        LinealCitizens(linealIdentity).mintProfile(wallet, username, imageURI, id);
        emit ProfileIssued(wallet, username, imageURI);
        emit CitizenAccountCreated(wallet, id);
    }

    function updateIdentityScore(
        uint256 tokenId,
        uint256 delta,
        bool positive
    ) external onlyServers {
        bytes32 txHash = _computeActionHash(
            "updateIdentityScore",
            abi.encode(tokenId, delta, positive)
        );

        if (!confirmServers(txHash, "updateIdentityScore")) return;

        LinealCitizens(linealIdentity).updateScore(
            tokenId,
            delta,
            positive
        );
    }

    /**
     * @notice Actualiza la imagen de un perfil existente. Requiere quórum de servers.
     */
    function setProfileImageURI(address wallet, string calldata newImageURI) external onlyServers {
        bytes32 txHash = _computeActionHash(
            "setProfileImageURI",
            abi.encode(wallet, newImageURI)
        );
        if (!confirmServers(txHash, "setProfileImageURI")) return;

        LinealCitizens(linealIdentity).setImageURI(wallet, newImageURI);
        emit ProfileImageUpdated(wallet, newImageURI);
    }

    function getDirectiva() external view returns (address[] memory) {
        return _directiva;
    }

    function setDescription(string calldata newDescription) external onlyQorum {
        bytes32 txHash = _computeActionHash("setDescription", abi.encode(newDescription));
        if (!confirm(txHash, "setDescription")) return;

        description = newDescription;
        emit DescriptionUpdated(newDescription);
    }

    // ───────────── Vistas ─────────────

    /**
     * @notice Devuelve todas las subcuentas creadas por esta Institución.
     */
    function getSubAccounts() external view returns (bytes32[] memory) {
        return subAccountIds;
    }

    /**
     * @notice Devuelve la dirección del banco vinculado a esta institución.
     */
    function getInstitutionBank() external view returns (address) {
        return address(institutionBank);
    }

    /**
     * @notice Devuelve la dirección del contrato de licitaciones (LinealTenders).
     */
    function getInstitutionTender() external view returns (address) {
        return institutionTender;
    }

    /**
     * @notice Devuelve la dirección del contrato de identidad (LinealCitizens).
     */
    function getIdentity() external view returns (address) {
        return linealIdentity;
    }

    function getRewardsAccountId() external view returns (bytes32) {
        return LinealBank(institutionBank).rewardsAccountId();
    }

    /**
     * @notice Tokens registrados en el banco (habilitados o no; ver `supportedToken` en el banco).
     */
    function getBankTokens() external view returns (address[] memory) {
        return LinealBank(institutionBank).tokenList();
    }

    /**
     * @notice Saldos de una subcuenta en todos los tokens registrados del banco.
     */
    function getAccountBalances(bytes32 accountId)
    external
    view
    returns (address[] memory tokens, uint256[] memory balances)
    {
        return LinealBank(institutionBank).accountBalancesAll(accountId);
    }
}

project/contracts/institution/LinealTend.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.30;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Base64.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title LinealTenders - NeoQuor
 * @notice Licitaciones como NFT. Cada licitación es un token (soulbound, en custodia de la
 * Institución) con título, descripción, imagen, URL del documento y su subcuenta en el banco.
 * Solo el owner (la Institución) puede emitirlas y modificarlas.
 */
contract LinealTender is ERC721, Ownable {

    uint256 public constant MAX_TITLE_LENGTH = 100; // bytes

    // Institución dueña de este contrato
    address public immutable institutionAddress;

    uint256 public tenderCounter;

    struct Tender {
        uint256 tokenId;
        string title;
        string description;
        string imageURI;
        string documentURL;
        uint256 amount;        // Monto de la licitación
        uint256 createdAt;
        bool active;
        bytes32 subAccountId;  // Subcuenta del banco asociada a la licitación
    }

    mapping(uint256 => Tender) private tenders;

    event TenderMinted(
        uint256 indexed tokenId,
        string title,
        string description,
        string imageURI,
        string documentURL,
        uint256 amount,
        bytes32 subAccountId
    );
    event TenderUpdated(
        uint256 indexed tokenId,
        string title,
        string description,
        string imageURI,
        string documentURL,
        uint256 amount
    );
    event TenderStatusChanged(uint256 indexed tokenId, bool active);

    error InvalidAddress();
    error EmptyTitle();
    error TitleTooLong();
    error EmptyDescription();
    error EmptyImageURI();
    error EmptyDocumentURL();
    error TenderDoesNotExist();
    error NonTransferable();
    error InvalidAmount();
    error InvalidSubAccount();

    /// @param _name               Nombre de la colección.
    /// @param _symbol             Símbolo de la colección.
    /// @param _institutionAddress Dueño del contrato (la Institución). Recibe los NFT.
    constructor(
        string memory _name,
        string memory _symbol,
        address _institutionAddress
    )
    ERC721(_name, _symbol)
    Ownable(_institutionAddress)
    {
        if (_institutionAddress == address(0)) revert InvalidAddress();
        institutionAddress = _institutionAddress;
    }

    /**
     * @notice Emite una licitación como NFT a la Institución (solo owner).
     * @param _title         Título (máx. 100 bytes).
     * @param _description   Descripción.
     * @param _imageURI      URL de la foto/imagen.
     * @param _documentURL   URL del documento de la licitación.
     * @param _amount        Monto de la licitación.
     * @param _subAccountId  Subcuenta del banco creada previamente por la Institución.
     */
    function mintTender(
        string calldata _title,
        string calldata _description,
        string calldata _imageURI,
        string calldata _documentURL,
        uint256 _amount,
        bytes32 _subAccountId
    ) external onlyOwner returns (uint256 tokenId) {
        _validate(_title, _description, _imageURI, _documentURL);

        if (_amount == 0) revert InvalidAmount();
        if (_subAccountId == bytes32(0)) revert InvalidSubAccount();

        tokenId = ++tenderCounter;

        tenders[tokenId] = Tender({
            tokenId: tokenId,
            title: _title,
            description: _description,
            imageURI: _imageURI,
            documentURL: _documentURL,
            amount: _amount,
            createdAt: block.timestamp,
            active: true,
            subAccountId: _subAccountId
        });

        _mint(institutionAddress, tokenId);

        emit TenderMinted(
            tokenId,
            _title,
            _description,
            _imageURI,
            _documentURL,
            _amount,
            _subAccountId
        );
    }

    /// @notice Actualiza los datos de una licitación existente (solo owner). La subcuenta no cambia.
    function updateTender(
        uint256 tokenId,
        string calldata _title,
        string calldata _description,
        string calldata _imageURI,
        string calldata _documentURL,
        uint256 amount
    ) external onlyOwner {
        if (_ownerOf(tokenId) == address(0)) revert TenderDoesNotExist();
        _validate(_title, _description, _imageURI, _documentURL);
        if (amount == 0) revert InvalidAmount();

        Tender storage t = tenders[tokenId];
        t.title = _title;
        t.description = _description;
        t.imageURI = _imageURI;
        t.documentURL = _documentURL;
        t.amount = amount;

        emit TenderUpdated(tokenId, _title, _description, _imageURI, _documentURL, amount);
    }

    /// @notice Abre o cierra una licitación (solo owner).
    function setTenderActive(uint256 tokenId, bool active) external onlyOwner {
        if (_ownerOf(tokenId) == address(0)) revert TenderDoesNotExist();
        tenders[tokenId].active = active;
        emit TenderStatusChanged(tokenId, active);
    }

    // --- LECTURA ---

    function getTender(uint256 tokenId) external view returns (Tender memory) {
        if (_ownerOf(tokenId) == address(0)) revert TenderDoesNotExist();
        return tenders[tokenId];
    }

    function getTenderCounter() external view returns (uint256) {
        return tenderCounter;
    }

    /// @notice Subcuenta del banco asociada a una licitación.
    function subAccountOf(uint256 tokenId) external view returns (bytes32) {
        if (_ownerOf(tokenId) == address(0)) revert TenderDoesNotExist();
        return tenders[tokenId].subAccountId;
    }

    /// @notice Lista todos los ids de licitaciones emitidas (1..tenderCounter).
    function getTenderIds() external view returns (uint256[] memory ids) {
        uint256 total = tenderCounter;
        ids = new uint256[](total);
        for (uint256 i = 0; i < total; i++) {
            ids[i] = i + 1;
        }
    }

    /// @notice Lista paginada de licitaciones completas (para evitar quedarse sin gas en lecturas grandes).
    /// @param offset Posición inicial (0 = primera licitación).
    /// @param limit  Máximo de resultados a devolver.
    function getTenders(uint256 offset, uint256 limit) external view returns (Tender[] memory page) {
        uint256 total = tenderCounter;
        if (offset >= total) return new Tender[](0);

        uint256 end = offset + limit;
        if (end > total) end = total;

        page = new Tender[](end - offset);
        for (uint256 i = offset; i < end; i++) {
            page[i - offset] = tenders[i + 1];
        }
    }

    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        if (_ownerOf(tokenId) == address(0)) revert TenderDoesNotExist();

        Tender storage t = tenders[tokenId];

        string memory json = Base64.encode(
            bytes(
                string.concat(
                    '{"name":"', _escape(t.title), '",',
                    '"description":"', _escape(t.description), '",',
                    '"image":"', _escape(t.imageURI), '",',
                    '"external_url":"', _escape(t.documentURL), '",',
                    _attributes(t),
                    '}'
                )
            )
        );

        return string.concat("data:application/json;base64,", json);
    }

    // --- INTERNAS ---

    function _attributes(Tender storage t) internal view returns (string memory) {
        return string.concat(
            '"attributes":[',
            '{"trait_type":"Institution","value":"', Strings.toHexString(institutionAddress), '"},',
            '{"trait_type":"Status","value":"', t.active ? "Active" : "Closed", '"},',
            '{"trait_type":"Account","value":"', Strings.toHexString(uint256(t.subAccountId), 32), '"},',
            '{"display_type":"date","trait_type":"Created","value":', Strings.toString(t.createdAt), '}',
            ']'
        );
    }

    /// @dev Soulbound: se puede mintear, pero no transferir entre wallets.
    function _update(
        address to,
        uint256 tokenId,
        address auth
    ) internal override returns (address) {
        address from = _ownerOf(tokenId);
        if (from != address(0) && to != address(0)) revert NonTransferable();
        return super._update(to, tokenId, auth);
    }

    function _validate(
        string calldata _title,
        string calldata _description,
        string calldata _imageURI,
        string calldata _documentURL
    ) internal pure {
        uint256 len = bytes(_title).length;
        if (len == 0) revert EmptyTitle();
        if (len > MAX_TITLE_LENGTH) revert TitleTooLong();
        if (bytes(_description).length == 0) revert EmptyDescription();
        if (bytes(_imageURI).length == 0) revert EmptyImageURI();
        if (bytes(_documentURL).length == 0) revert EmptyDocumentURL();
    }

    /// @dev Escapa comillas, backslash y saltos de línea para no romper el JSON del tokenURI.
    function _escape(string memory s) internal pure returns (string memory) {
        bytes memory b = bytes(s);
        bytes memory out = new bytes(b.length * 2);
        uint256 j;
        for (uint256 i = 0; i < b.length; i++) {
            bytes1 c = b[i];
            if (c == 0x22 || c == 0x5c) {            // " o \
                out[j++] = 0x5c;
                out[j++] = c;
            } else if (c == 0x0a) {                  // \n
                out[j++] = 0x5c;
                out[j++] = 0x6e;
            } else if (c == 0x0d || c == 0x09) {     // \r, \t -> espacio
                out[j++] = 0x20;
            } else {
                out[j++] = c;
            }
        }
        bytes memory trimmed = new bytes(j);
        for (uint256 k = 0; k < j; k++) {
            trimmed[k] = out[k];
        }
        return string(trimmed);
    }
}
